package com.only4u\n\nimport android.Manifest\nimport android.content.pm.PackageManager\nimport android.os.Build\nimport android.os.Bundle\nimport android.view.inputmethod.EditorInfo\nimport android.widget.Toast\nimport androidx.appcompat.app.AppCompatActivity\nimport androidx.core.app.ActivityCompat\nimport androidx.core.content.ContextCompat\nimport androidx.lifecycle.lifecycleScope\nimport androidx.recyclerview.widget.LinearLayoutManager\nimport com.only4u.databinding.ActivityMainBinding\nimport kotlinx.coroutines.launch\n\nclass MainActivity : AppCompatActivity() {\n    private lateinit var binding: ActivityMainBinding\n    private lateinit var messageAdapter: MessageAdapter\n    private lateinit var llamaService: LlamaService\n    private var isGenerating = false\n\n    companion object {\n        private const val PERMISSION_REQUEST_CODE = 100\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        binding = ActivityMainBinding.inflate(layoutInflater)\n        setContentView(binding.root)\n\n        requestPermissionsIfNeeded()\n        initializeUI()\n        initializeLlama()\n    }\n\n    private fun requestPermissionsIfNeeded() {\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {\n            if (ContextCompat.checkSelfPermission(\n                    this,\n                    Manifest.permission.MANAGE_EXTERNAL_STORAGE\n                ) != PackageManager.PERMISSION_GRANTED\n            ) {\n                ActivityCompat.requestPermissions(\n                    this,\n                    arrayOf(Manifest.permission.MANAGE_EXTERNAL_STORAGE),\n                    PERMISSION_REQUEST_CODE\n                )\n            }\n        } else {\n            if (ContextCompat.checkSelfPermission(\n                    this,\n                    Manifest.permission.WRITE_EXTERNAL_STORAGE\n                ) != PackageManager.PERMISSION_GRANTED\n            ) {\n                ActivityCompat.requestPermissions(\n                    this,\n                    arrayOf(\n                        Manifest.permission.READ_EXTERNAL_STORAGE,\n                        Manifest.permission.WRITE_EXTERNAL_STORAGE\n                    ),\n                    PERMISSION_REQUEST_CODE\n                )\n            }\n        }\n    }\n\n    private fun initializeUI() {\n        messageAdapter = MessageAdapter()\n        binding.messageRecyclerView.apply {\n            adapter = messageAdapter\n            layoutManager = LinearLayoutManager(this@MainActivity).apply {\n                stackFromEnd = true\n            }\n        }\n\n        binding.sendButton.setOnClickListener { sendMessage() }\n        binding.inputEditText.setOnEditorActionListener { _, actionId, _ ->\n            if (actionId == EditorInfo.IME_ACTION_SEND) {\n                sendMessage()\n                true\n            } else {\n                false\n            }\n        }\n\n        binding.clearButton.setOnClickListener { clearChat() }\n    }\n\n    private fun initializeLlama() {\n        try {\n            llamaService = LlamaService(this)\n            Toast.makeText(this, \"Llama service initialized\", Toast.LENGTH_SHORT).show()\n        } catch (e: Exception) {\n            Toast.makeText(this, \"Failed to initialize Llama: ${e.message}\", Toast.LENGTH_LONG)\n                .show()\n        }\n    }\n\n    private fun sendMessage() {\n        val userInput = binding.inputEditText.text.toString().trim()\n        if (userInput.isEmpty() || isGenerating) return\n\n        messageAdapter.addMessage(Message(userInput, isUser = true))\n        binding.messageRecyclerView.smoothScrollToPosition(messageAdapter.itemCount - 1)\n        binding.inputEditText.text.clear()\n        binding.sendButton.isEnabled = false\n        isGenerating = true\n\n        lifecycleScope.launch {\n            try {\n                val response = llamaService.generate(userInput)\n                messageAdapter.addMessage(Message(response, isUser = false))\n                binding.messageRecyclerView.smoothScrollToPosition(messageAdapter.itemCount - 1)\n            } catch (e: Exception) {\n                messageAdapter.addMessage(\n                    Message(\n                        \"Error: ${e.message}\",\n                        isUser = false\n                    )\n                )\n            } finally {\n                isGenerating = false\n                binding.sendButton.isEnabled = true\n            }\n        }\n    }\n\n    private fun clearChat() {\n        messageAdapter.clear()\n        binding.messageRecyclerView.smoothScrollToPosition(0)\n    }\n\n    override fun onDestroy() {\n        super.onDestroy()\n        llamaService.release()\n    }\n}\n\ndata class Message(\n    val text: String,\n    val isUser: Boolean,\n    val timestamp: Long = System.currentTimeMillis()\n)